type_of_examination = frappe.form_dict.get("type_of_examination")

if type_of_examination == "Random Test":
    result = frappe.db.sql(""" SELECT parameter_type, measure_name, measure_code, uom FROM `tabMedical Parameters` WHERE parameter_type = 'Random Check' """, as_dict = 1)
else:
    result = frappe.db.sql(""" SELECT parameter_type, measure_name, measure_code, uom FROM `tabMedical Parameters`  WHERE parameter_type != 'Random Check' """, as_dict = 1)

frappe.response["message"] = result

starting_from = int(frappe.form_dict.get("starting_from"))
ending_at = int(frappe.form_dict.get("ending_at"))
company = frappe.form_dict.get("company")

if ending_at < starting_from:
    frappe.response["message"] = {
        "status": False,
        "message": "Invalid Starting and Ending Code"
    }

if ending_at <= 0 or starting_from <= 0:
    frappe.response["message"] = {
        "status": False,
        "message": "Invalid Starting and Ending Code"
    }

companies = frappe.db.sql("""
    SELECT 
        name
    FROM tabCompany
    WHERE 
        %s BETWEEN custom_employee_code_starting_from and custom_employee_code_ending_at
        OR
        %s BETWEEN custom_employee_code_starting_from and custom_employee_code_ending_at
""", (starting_from, ending_at), as_dict=True)

if companies:
    frappe.response["message"] = {
        "status": False,
        "message": f"Series already used in {companies[0].name}"
    }


frappe.db.set_value("Company", company, "custom_employee_code_starting_from", starting_from)
frappe.db.set_value("Company", company, "custom_employee_code_ending_at", ending_at)

frappe.response["message"] = {
    "status": True,
    "message": "Reset Successful"
}

salary_slip = frappe.form_dict.get("salary_slip")

ss = frappe.get_doc("Salary Slip", salary_slip)

if ss.salary_slip:

    employee_status = frappe.db.get_value("Employee", ss.employee, "status")
    email = frappe.db.get_value("Employee", ss.employee, "company_email")

    if employee_status != "Active":
        email = frappe.db.get_value("Employee", ss.employee, "personal_email")

